// ─── Hard Map: Client Name → Acronis Tenant ID ───────────────────────────────
// null = no matching Acronis tenant found (not yet onboarded or name unknown)

const CLIENT_TENANT_MAP = {
  "Contoso Ltd":       "00000000-0000-0000-0000-000000000001",
  "Fabrikam Inc":      "00000000-0000-0000-0000-000000000002",
  "Northwind Traders": null,
};

// ─── Lookup ───────────────────────────────────────────────────────────────────
const input = $input.first().json;
const clientName = input["Client Name"] ?? "";
const tenantId = CLIENT_TENANT_MAP[clientName] ?? null;

return [{
  json: {
    ...input,
    acronis: {
      matched: tenantId !== null,
      tenantId: tenantId,
    }
  }
}];

return [
  {
    json: {
      summary: "No acronis data found",
    },
  },
];

const allInputs = $input.all().map((i) => i.json);
const input = allInputs.length > 1 ? allInputs : allInputs[0];

// Support: [{ items: [...] }], { items: [...] }, or a flat usage array
let usageItems = [];
if (Array.isArray(input) && input[0]?.items) {
  usageItems = input[0].items;
} else if (Array.isArray(input?.items)) {
  usageItems = input.items;
} else if (Array.isArray(input) && input[0]?.usage_name) {
  usageItems = input;
} else if (Array.isArray(input?.body?.[0]?.items)) {
  usageItems = input.body[0].items;
} else {
  throw new Error('Could not find usage items array in input');
}

const BYTES_PER_TB = 1024 ** 4;
const BYTES_PER_GB = 1024 ** 3;

function bytesToTb(bytes) {
  return Math.round((bytes / BYTES_PER_TB) * 100) / 100;
}

function bytesToGb(bytes) {
  return Math.round((bytes / BYTES_PER_GB) * 100) / 100;
}

function find(name, opts = {}) {
  return usageItems.find((i) => {
    if (i.name !== name) return false;
    if (opts.edition && i.edition !== opts.edition) return false;
    if (opts.status !== undefined && i.offering_item?.status !== opts.status) return false;
    if (opts.infra_id && i.infra_id !== opts.infra_id) return false;
    return true;
  });
}

function val(item) {
  return item?.value ?? item?.absolute_value ?? 0;
}

// Prefer active (status 1) per-workload rows with real usage
const storage = find('pw_base_storage', { edition: 'pck_per_workload', status: 1 })
  || usageItems.find((i) => i.name === 'pw_base_storage' && val(i) > 0);

const drStorage = find('pw_base_adv_dr_storage', { edition: 'pck_per_workload', status: 1 })
  || usageItems.find((i) => i.name === 'pw_base_adv_dr_storage' && val(i) > 0);

const workstations = find('pw_base_workstations', { status: 1 });
const servers = find('pw_base_servers', { status: 1 });
const vms = find('pw_base_vms', { status: 1 });
const totalWorkloads = find('total_protected_workloads');
const totalStorage = find('total_storage');

const backupInfraId = storage?.infra_id;
const drInfraId = drStorage?.infra_id;

const workstationStorage = usageItems.find((i) => i.name === 'workstation_storage' && i.infra_id === backupInfraId);
const serverStorage = usageItems.find((i) => i.name === 'server_storage' && i.infra_id === backupInfraId);
const vmStorage = usageItems.find((i) => i.name === 'vm_storage' && i.infra_id === backupInfraId);
const immutableStorage = usageItems.find((i) => i.name === 'immutable_storage' && i.infra_id === backupInfraId);

const drCloudServers = find('pw_base_adv_dr_cloud_servers', { status: 1 });
const assignedCompute = usageItems.find((i) => i.name === 'assigned_compute_points' && i.infra_id === drInfraId);
const publicIps = find('pw_base_adv_dr_public_ips', { status: 1 });
const computePoints = find('pw_base_adv_dr_compute_points', { status: 1 });

const sample = storage || workstations || usageItems[0];

const summary = {
  tenant_id: sample?.tenant_id ?? null,
  tenant_uuid: sample?.tenant_uuid ?? null,
  period: sample?.range_start ?? null,
  edition: 'pck_per_workload',

  protected_workloads: {
    total: val(totalWorkloads),
    workstations: val(workstations),
    servers: val(servers),
    vms: val(vms),
  },

  backup_storage: {
    infra_id: backupInfraId ?? null,
    total_bytes: val(storage) || val(totalStorage),
    total_tb: bytesToTb(val(storage) || val(totalStorage)),
    workstations_tb: bytesToTb(val(workstationStorage)),
    servers_tb: bytesToTb(val(serverStorage)),
    vms_tb: bytesToTb(val(vmStorage)),
    immutable_tb: bytesToTb(val(immutableStorage)),
    workstations_bytes: val(workstationStorage),
    servers_bytes: val(serverStorage),
    vms_bytes: val(vmStorage),
    immutable_bytes: val(immutableStorage),
  },

  disaster_recovery: {
    infra_id: drInfraId ?? null,
    storage_bytes: val(drStorage),
    storage_tb: bytesToTb(val(drStorage)),
    cloud_servers: val(drCloudServers),
    assigned_compute_points_seconds: val(assignedCompute),
    public_ips: val(publicIps),
    compute_points_used: val(computePoints),
  },

  // Human-readable one-liner
  bottom_line: (() => {
    const wl = val(totalWorkloads);
    const bak = bytesToTb(val(storage) || val(totalStorage));
    const dr = bytesToTb(val(drStorage));
    const drServers = val(drCloudServers);
    return `Per-workload billing: ${wl} protected devices `
      + `(${val(workstations)} WS + ${val(servers)} servers + ${val(vms)} VMs), `
      + `~${bak} TB backup storage, ~${dr} TB DR storage, ${drServers} DR cloud servers.`;
  })(),
};

return [{ json: summary }];

const editionLabels = {
  pck_per_workload: 'Per-workload',
  pck_per_gigabyte: 'Per-gigabyte',
};

function summarize(row) {
  const workloads = row.protected_workloads || {};
  const backup = row.backup_storage || {};
  const dr = row.disaster_recovery || {};

  const period = row.period
    ? DateTime.fromISO(row.period).toFormat('yyyy-MM')
    : null;

  const edition = editionLabels[row.edition] || row.edition || null;

  const protectedWorkloads = workloads.total ?? 0;
  const workstations = workloads.workstations ?? 0;
  const servers = workloads.servers ?? 0;
  const vms = workloads.vms ?? 0;

  const backupTb = backup.total_tb ?? 0;
  const drTb = dr.storage_tb ?? 0;
  const drCloudServers = dr.cloud_servers ?? 0;

  const summary =
    row.bottom_line ||
    `${edition || 'Billing'}: ${protectedWorkloads} protected devices ` +
      `(${workstations} WS + ${servers} servers + ${vms} VMs), ` +
      `~${backupTb} TB backup, ~${drTb} TB DR, ${drCloudServers} DR cloud servers.`;

  return {
    period,
    edition,
    protected_workloads: protectedWorkloads,
    workstations,
    servers,
    vms,
    backup_storage_tb: backupTb,
    dr_storage_tb: drTb,
    dr_cloud_servers: drCloudServers,
    summary,
  };
}

// Supports: array on first item, or one usage object per item
const raw = $input.first().json;
const rows = Array.isArray(raw)
  ? raw
  : Array.isArray(raw?.data)
    ? raw.data
    : $input.all().map((i) => i.json);

return rows.map((row) => ({ json: summarize(row) }));
